import{_ as n,o,c as t,a3 as a}from"./chunks/framework.B5WAEDB7.js";const u=JSON.parse('{"title":"Sensors and time synchronization","description":"Diagnose timestamp, latency, and synchronization problems that appear as unstable multi-sensor fusion.","frontmatter":{"title":"Sensors and time synchronization","description":"Diagnose timestamp, latency, and synchronization problems that appear as unstable multi-sensor fusion.","content_type":"knowledge","status":"design guidance","scope":"multi-sensor autonomous-driving pipelines","keywords":["sensor timestamp","latency","PTP","fusion jitter","Cyber RT"],"evidence_ids":[]},"headers":[],"relativePath":"en/knowledge/sensors-and-time.md","filePath":"en/knowledge/sensors-and-time.md","lastUpdated":1794216847000}'),i={name:"en/knowledge/sensors-and-time.md"};function s(r,e,l,c,d,m){return o(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="sensors-and-time-synchronization" tabindex="-1">Sensors and time synchronization <a class="header-anchor" href="#sensors-and-time-synchronization" aria-label="Permalink to &quot;Sensors and time synchronization&quot;">​</a></h1><p><strong>Status:</strong> <code>design guidance</code> · <strong>Scope:</strong> multi-sensor autonomous-driving pipelines</p><h2 id="common-symptoms" tabindex="-1">Common symptoms <a class="header-anchor" href="#common-symptoms" aria-label="Permalink to &quot;Common symptoms&quot;">​</a></h2><ul><li>Sensor rates look normal, but fused objects smear or jump.</li><li>Replay is stable while the online system is unstable.</li><li>Every device reports Unix time, yet messages still cannot be aligned.</li></ul><h2 id="diagnostic-order" tabindex="-1">Diagnostic order <a class="header-anchor" href="#diagnostic-order" aria-label="Permalink to &quot;Diagnostic order&quot;">​</a></h2><ol><li>Record acquisition, publication, receipt, timestamp, and sequence number separately. Do not inspect only one middleware field.</li><li>Measure message-period distribution, latency, and cross-sensor time offset, including tail behavior rather than only averages.</li><li>Confirm each device&#39;s clock source, synchronization protocol, and time-zone/monotonic-clock semantics.</li><li>Replay a fixed dataset while sweeping offsets to quantify sensitivity.</li><li>Preserve metrics and failure samples before and after any synchronization fix.</li></ol><h2 id="what-cannot-be-concluded-yet" tabindex="-1">What cannot be concluded yet <a class="header-anchor" href="#what-cannot-be-concluded-yet" aria-label="Permalink to &quot;What cannot be concluded yet&quot;">​</a></h2><p>Claiming &quot;time synchronization is solved&quot; requires a reproducible environment, measured offset, correction method, and acceptance metric. The WheelOS roadmap mentions synchronization tooling, but this page does not treat the roadmap as implementation or vehicle-validation evidence.</p>',8)])])}const h=n(i,[["render",s]]);export{u as __pageData,h as default};
